def transform(grid):
    h=len(grid); w=len(grid[0])
    out=[row[:] for row in grid]
    # find horizontal lines: rows with nonzero cells, group into same-color runs, fill gaps between runs of same color
    hrows={}
    for r in range(h):
        cells=[(j,v) for j,v in enumerate(grid[r]) if v]
        if not cells: continue
        # runs of same color
        runs=[]; cur=None
        for j,v in cells:
            if cur and cur[2]==v and j==cur[1]+1: cur=(cur[0],j,v)
            else:
                if cur: runs.append(cur)
                cur=(j,j,v)
        if cur: runs.append(cur)
        hrows[r]=runs
        # fill gaps between consecutive runs of same color
        for (a1,b1,c1),(a2,b2,c2) in zip(runs,runs[1:]):
            if c1==c2:
                for j in range(b1+1,a2): out[r][j]=c1
    # vertical stubs: columns with nonzero cells forming vertical runs not part of horizontal rows? treat any column whose nonzero cells all lie below the lowest... simpler: a cell (r,j) nonzero where the row is not a horizontal row -> vertical stub cell
    nonh={r for r in range(h) if r not in hrows}
    stubcols={}
    for r in range(h):
        for j,v in enumerate(grid[r]):
            if v and r in nonh: stubcols.setdefault(j,set()).add(v)
    for c,cols in stubcols.items():
        stub=sorted(cols)[0]
        for r in range(h):
            # nearest horizontal row >= r covering column c (after fill)
            best=None
            for rr in range(r,h):
                if rr in hrows and any(a<=c<=b for a,b,_ in hrows[rr]):
                    # color at (rr,c) after fill
                    best=out[rr][c]; break
            out[r][c]=best if best else stub
    return out

