def transform(grid):
    h=len(grid); w=len(grid[0])
    out=[row[:] for row in grid]
    # classify: horizontal row = has a run of >=2 same-color nonzero cells
    hrows=set()
    for r in range(h):
        row=grid[r]; j=0
        while j<w:
            if row[j]:
                k=j
                while k+1<w and row[k+1]==row[j]: k+=1
                if k>j: hrows.add(r)
                j=k+1
            else: j+=1
    # fill gaps in horizontal rows between consecutive same-color runs
    for r in hrows:
        row=out[r]; j=0
        while j<w:
            if row[j]:
                k=j
                while k+1<w and row[k+1]==row[j]: k+=1
                m=k+1
                if m<w and row[m]==0:
                    n=m
                    while n<w and row[n]==0: n+=1
                    if n<w and row[n]==row[j]:
                        for t in range(m,n): row[t]=row[j]
                    j=n
                else: j=k+1
            else: j+=1
    # vertical stubs
    stubcols={}
    for r in range(h):
        if r in hrows: continue
        for j,v in enumerate(grid[r]):
            if v: stubcols.setdefault(j,v)
    for c,stub in stubcols.items():
        for r in range(h):
            best=None
            for rr in range(r,h):
                if rr in hrows and out[rr][c]: best=out[rr][c]; break
            out[r][c]=best if best is not None else stub
    return out

